package org.apache.commons.math3.optimization.univariate;

import org.apache.commons.math3.analysis.UnivariateFunction;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.univariate.BrentOptimizer;
import org.apache.commons.math3.optimization.univariate.UnivariatePointValuePair;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_24_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Define a function with multiple local minima: f(x) = sin(x) + 0.1 * x
        UnivariateFunction function = new UnivariateFunction() {
            public double value(double x) {
                return Math.sin(x) + 0.1 * x;
            }
        };

        // Create a BrentOptimizer instance with reasonable thresholds
        BrentOptimizer optimizer = new BrentOptimizer(1e-10, 1e-14);

        // Attempt to find the minimum of the function in the interval [0, 10]
        UnivariatePointValuePair result = optimizer.optimize(100, function, GoalType.MINIMIZE, 0, 10);

        // The expected minimum is around x = -1.5 (local minimum of sin(x) + 0.1 * x)
        assertEquals(-1.5, result.getPoint(), 0.1);
    }
}

